#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <signal.h>
#include <sys/wait.h>


void sigchld_handler(int signo)
{
    /* 循环收干净所有已经退出的子进程 */
    while (waitpid(-1, NULL, WNOHANG) > 0)
        ;
}

int main(int argc, char *argv[])
{

    signal(SIGCHLD, sigchld_handler);
    char buf[256];
    int port = (argc > 1) ? atoi(argv[1]) : 8080;

    int listen_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (listen_fd < 0) { perror("socket"); return 1; }

    int ep = epoll_create(0);
    struct epoll_event ev,events[64];

    ev.events = EPOLLIN;
    ev.data.fd = listen_fd;
    epoll_ctl(ep,EPOLL_CTL_ADD,listen_fd,&ev);

    int opt = 1;
    setsockopt(listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_port        = htons(port);
    addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(listen_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); return 1;
    }
    if (listen(listen_fd, 5) < 0) { perror("listen"); return 1; }

    printf("监听 %d，等待连接...\n", port);      /* ★ 打印真实端口 */

    while (1) {                                   /* ★ 外层：等下一个客人 */

        int n = epoll_wait(ep, events, 64, -1);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("epoll_wait"); break;
        }

        for (int i = 0; i < n; i++) {
            int fd = events[i].data.fd;

            if (fd == listen_fd) {
                /* ===== 有新客人 ===== */
                int conn_fd = accept(listen_fd, NULL, NULL);
                if (conn_fd < 0) continue;
                printf("新连接 conn_fd = %d\n", conn_fd);
                epoll_ctl(ep,EPOLL_CTL_ADD,conn_fd,&ev);
                int n = epoll_wait(ep, events, 64, 0);
                for(int i = 0; i < n; i++) {
                    int fd = events[i].data.fd;
                    if(fd != listen_fd) {
                        int n = read(fd, buf, sizeof(buf));
                        if(n == 0) {
                            epoll_ctl(ep,EPOLL_CTL_DEL,fd,NULL);
                            close(fd);
                        } else {
                            write(fd, buf, n);
                        }
                        }
                    }
                }
            } else {
                /* ===== 老客人有话说 ===== */
                /* 你自己写：
                    read(fd, ...)
                    n == 0 → 客人走了：epoll_ctl(ep, EPOLL_CTL_DEL, fd, NULL) + close(fd)
                    n  > 0 → write(fd, buf, n) 原样发回
                */
            }
        }
    }
    close(listen_fd);
    return 0;
}
        有点卡住了

卡住的地方我看到了 —— **你在"新客人"分支里又嵌了一个 `epoll_wait` 循环**。那是多余的，而且正是它让代码绕晕了。

先说三个具体错误，再讲结构。

# ① 缺两个头文件

```c
#include <sys/epoll.h>      /* epoll_create1 / epoll_ctl / epoll_wait */
#include <errno.h>          /* EINTR */
```

# ② `epoll_create(0)` 会失败

```c
int ep = epoll_create(0);       /* ✗ 参数必须 > 0，传 0 返回 EINVAL */
```

用新接口：

```c
int ep = epoll_create1(0);      /* ✓ 这里的 0 是 flags，不是 size */
if (ep < 0) { perror("epoll_create1"); return 1; }
```

（`epoll_create(size)` 是老接口，那个 `size` 早就没用了但不能填 0。`epoll_create1` 是替代品。）

# ③ ★ 最隐蔽的 bug：`ev.data.fd` 忘了改

```c
ev.data.fd = listen_fd;                          /* 一开始设成 listen_fd */
epoll_ctl(ep, EPOLL_CTL_ADD, listen_fd, &ev);
...
epoll_ctl(ep, EPOLL_CTL_ADD, conn_fd, &ev);      /* ★ ev.data.fd 还是 listen_fd！ */
```

**`data.fd` 是"你让内核替你记的标签"** —— 将来这个 fd 有动静时，内核原样还给你。

你没改，所以内核记的是"这张牌叫 listen_fd"。等客人发数据时，`events[i].data.fd` 报回来的是 `listen_fd` → 你的代码会跑去 `accept` → 一片混乱。

**加进去之前必须先改**：

```c
ev.events  = EPOLLIN;
ev.data.fd = conn_fd;                            /* ★ 先改 */
epoll_ctl(ep, EPOLL_CTL_ADD, conn_fd, &ev);
```

---

# ④ 结构：不要嵌套 `epoll_wait`

**外层的 `while (1)` 已经在不停地 `epoll_wait` 了。** 新客人的数据不需要你当场去读 —— **下一轮 `epoll_wait` 自然会告诉你**。

正确的心智模型：

```
while (1) {
    epoll_wait()  →  内核返回"这几张牌有动静"

    for (每张有动静的牌) {
        是 listen_fd ？ → accept，把新牌加进名单。【完事，不读数据】
        否则           ？ → read 一次，处理一次。【完事，不循环】
    }
}                     ← 回到 epoll_wait，等下一批
```

**每轮只做小事，马上回去等。** 这就是事件驱动。

**新客人第一次发数据，会在下一轮 `epoll_wait` 被报告。** 你不用管，内核会记着。

---

# 正确的主循环

```c
while (1) {
    int n = epoll_wait(ep, events, 64, -1);
    if (n < 0) {
        if (errno == EINTR) continue;
        perror("epoll_wait"); break;
    }

    for (int i = 0; i < n; i++) {
        int fd = events[i].data.fd;

        if (fd == listen_fd) {
            /* ===== 新客人 ===== */
            int conn_fd = accept(listen_fd, NULL, NULL);
            if (conn_fd < 0) { perror("accept"); continue; }
            printf("新连接 conn_fd = %d\n", conn_fd);

            ev.events  = EPOLLIN;
            ev.data.fd = conn_fd;                      /* ★ 别忘 */
            epoll_ctl(ep, EPOLL_CTL_ADD, conn_fd, &ev);

        } else {
            /* ===== 老客人有话说 ===== */
            ssize_t cnt = read(fd, buf, sizeof(buf));  /* 只读一次 */

            if (cnt <= 0) {
                if (cnt < 0) perror("read");
                printf("conn_fd = %d 走了\n", fd);
                epoll_ctl(ep, EPOLL_CTL_DEL, fd, NULL);  /* 从名单里摘掉 */
                close(fd);
            } else {
                write(fd, buf, cnt);                     /* 原样发回 */
            }
        }
    }
}
```

**注意里面没有任何一处循环读到 EOF。** 每个 fd 都是"读一次、处理一次、走人"。

---

# 另外两处小调整

**`epoll_ctl` 挪到 `listen` 之后**

你现在把 `listen_fd` 加进 epoll 是在 `bind`/`listen` 之前。技术上能工作，但逻辑上应该是"先把监听建好，再交给 epoll 盯着"。挪到 `printf("监听 %d...")` 那行前面。

**`SIGCHLD` 那套可以删了**

epoll 版不 fork，没有子进程，也就没有僵尸。`sigchld_handler`、`signal()`、两个头文件都可以去掉。

（留着不报错，但是死代码 —— 会误导以后读代码的人以为这里有子进程。）

---

改完编译跑：

```sh
./19_epoll 9002 &
./18_probe 9002
./18_probe 9002
```

然后做**关键实验** —— 一个进程同时伺候两个客人：

```sh
./17_hog 9002 &          # A 占住 15 秒不说话
sleep 1
./18_probe 9002          # B
```

**先猜 B 等几秒？** 提示：现在只有**一个进程**，没有 fork，但它不会卡在 A 的 `read` 上。

